"use client";

import { useMemo, useRef, useState, type ReactNode } from "react";
import { Instrument_Sans } from "next/font/google";
import { Zip, ZipDeflate, ZipPassThrough, unzipSync } from "fflate";
import {
  buildTree,
  formatBytes,
  isRemoved,
  keptEntries,
  removalSummary,
  toggleSelection,
  type TreeNode,
  type ZipEntryInfo,
} from "@/lib/zipTree";

import {
  Check,
  ChevronDown,
  ChevronRight,
  CircleAlert,
  Download,
  File,
  FileArchive,
  FileCode,
  FileImage,
  FileText,
  Folder,
  FolderOpen,
  RotateCcw,
  Upload,
  X,
} from "lucide-react";

/*
  Palette
  bg        #080B10   page
  surface   #111821   panels
  well      #0B1220   inset areas, headers
  raised    #162333   hover / tracks
  line      #263548   borders
  line-2    #34495E   stronger borders
  text      #F4F8FC   primary text
  text-2    #A8B4C2   secondary text
  text-3    #64748B   tertiary text
  accent    #00D9FF   primary action (hover #66E5FF)
  danger    #FF4D5A   removal
  ok        #35E69B   success
*/

const sans = Instrument_Sans({ subsets: ["latin"], display: "swap" });

type Status = "idle" | "building" | "done";

const focusRing =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#66E5FF] focus-visible:ring-offset-2 focus-visible:ring-offset-[#080B10]";

const fileIcon = (name: string) => {
  const ext = name.split(".").pop()?.toLowerCase() ?? "";

  if (["png", "jpg", "jpeg", "svg", "webp", "gif"].includes(ext))
    return <FileImage size={16} strokeWidth={1.5} />;

  if (["js", "ts", "tsx", "jsx", "html", "css", "json", "py"].includes(ext))
    return <FileCode size={16} strokeWidth={1.5} />;

  if (["pdf", "doc", "docx", "txt", "md"].includes(ext))
    return <FileText size={16} strokeWidth={1.5} />;

  return <File size={16} strokeWidth={1.5} />;
};

export default function ZipOrganizer() {
  const [file, setFile] = useState<File | null>(null);
  const [entries, setEntries] = useState<ZipEntryInfo[]>([]);
  const [selected, setSelected] = useState<Set<string>>(new Set());
  const [expanded, setExpanded] = useState<Set<string>>(new Set());
  const [error, setError] = useState<string | null>(null);
  const [status, setStatus] = useState<Status>("idle");
  const [progress, setProgress] = useState(0);
  const [dragging, setDragging] = useState(false);

  const inputRef = useRef<HTMLInputElement>(null);

  const tree = useMemo(() => buildTree(entries), [entries]);
  const summary = useMemo(
    () => removalSummary(entries, selected),
    [entries, selected]
  );

  const fileCount = entries.filter((e) => !e.path.endsWith("/")).length;
  const folderCount = entries.filter((e) => e.path.endsWith("/")).length;
  const kept = keptEntries(entries, selected);
  const keptCount = kept.filter((e) => !e.path.endsWith("/")).length;

  const totalBytes = useMemo(
    () =>
      entries.reduce(
        (sum, e) => (e.path.endsWith("/") ? sum : sum + e.size),
        0
      ),
    [entries]
  );
  const removedPct =
    totalBytes > 0 ? Math.min(100, (summary.bytes / totalBytes) * 100) : 0;

  const cleanedName = file
    ? file.name.replace(/\.zip$/i, "") + "-cleaned.zip"
    : "";
  const building = status === "building";

  async function onPick(f: File | undefined) {
    if (!f) return;

    setStatus("idle");
    setProgress(0);

    try {
      const data = new Uint8Array(await f.arrayBuffer());
      const list: ZipEntryInfo[] = [];

      unzipSync(data, {
        filter(info) {
          list.push({
            path: info.name,
            size: info.originalSize,
          });
          return false;
        },
      });

      setFile(f);
      setEntries(list);
      setSelected(new Set());
      setExpanded(new Set());
      setError(null);
    } catch {
      setError(
        `"${f.name}" could not be opened. The archive may be corrupted, encrypted, or unsupported.`
      );
    } finally {
      if (inputRef.current) inputRef.current.value = "";
    }
  }

  async function rebuild() {
    if (!file) return;

    setStatus("building");
    setProgress(0);
    setError(null);

    try {
      const keep = new Set(keptEntries(entries, selected).map((e) => e.path));

      const data = new Uint8Array(await file.arrayBuffer());

      const files = unzipSync(data, {
        filter: (info) => keep.has(info.name),
      });

      const names = Object.keys(files);

      const blob = await new Promise<Blob>((resolve, reject) => {
        const chunks: Uint8Array[] = [];

        const zip = new Zip((err, chunk, final) => {
          if (err) return reject(err);

          chunks.push(chunk);

          if (final) {
            resolve(
              new Blob(chunks as BlobPart[], {
                type: "application/zip",
              })
            );
          }
        });

        (async () => {
          for (let i = 0; i < names.length; i++) {
            const name = names[i];

            const entry = name.endsWith("/")
              ? new ZipPassThrough(name)
              : new ZipDeflate(name, { level: 6 });

            zip.add(entry);
            entry.push(files[name], true);

            setProgress(
              Math.round(((i + 1) / Math.max(names.length, 1)) * 100)
            );

            await new Promise((r) => setTimeout(r, 0));
          }

          zip.end();
        })().catch(reject);
      });

      const url = URL.createObjectURL(blob);
      const a = document.createElement("a");

      a.href = url;
      a.download = cleanedName;
      a.click();

      setTimeout(() => URL.revokeObjectURL(url), 10000);

      setStatus("done");
    } catch {
      setStatus("idle");
      setError(
        "Archive reconstruction failed. Your selections are preserved. Please try again."
      );
    }
  }

  function closeArchive() {
    setFile(null);
    setEntries([]);
    setSelected(new Set());
    setExpanded(new Set());
    setStatus("idle");
    setProgress(0);
    setError(null);
  }

  function toggleExpand(path: string) {
    setExpanded((prev) => {
      const next = new Set(prev);
      if (!next.delete(path)) next.add(path);
      return next;
    });
  }

  function expandAll(nodes: TreeNode[]) {
    const paths = new Set<string>();

    function walk(node: TreeNode) {
      if (node.isDir) paths.add(node.path);
      node.children.forEach(walk);
    }

    nodes.forEach(walk);
    setExpanded(paths);
  }

  function collapseAll() {
    setExpanded(new Set());
  }

  function renderNode(node: TreeNode, depth: number): ReactNode {
    const removed = isRemoved(node.path, selected);
    const inherited = removed && !selected.has(node.path);
    const open = expanded.has(node.path);

    const label = (
      <>
        <span className={node.isDir ? "text-[#00D9FF]" : "text-[#64748B]"}>
          {node.isDir ? (
            open ? (
              <FolderOpen size={17} strokeWidth={1.5} />
            ) : (
              <Folder size={17} strokeWidth={1.5} />
            )
          ) : (
            fileIcon(node.name)
          )}
        </span>
        <span
          className={`min-w-0 flex-1 truncate text-left text-[13px] ${
            removed ? "text-[#64748B] line-through" : "text-[#F4F8FC]"
          }`}
        >
          {node.name}
        </span>
      </>
    );

    return (
      <li key={node.path}>
        <div
          className={`flex h-9 items-center gap-2.5 border-l-2 pr-4 transition-colors ${
            removed
              ? "border-[#FF4D5A] bg-[#FF4D5A]/[0.07]"
              : "border-transparent hover:bg-[#162333]"
          }`}
          style={{ paddingLeft: `${10 + depth * 20}px` }}
        >
          {node.isDir ? (
            <button
              onClick={() => toggleExpand(node.path)}
              className={`flex h-5 w-5 shrink-0 items-center justify-center rounded text-[#64748B] hover:text-[#F4F8FC] ${focusRing}`}
              aria-label={open ? `Collapse ${node.name}` : `Expand ${node.name}`}
              aria-expanded={open}
            >
              {open ? <ChevronDown size={15} /> : <ChevronRight size={15} />}
            </button>
          ) : (
            <span className="w-5 shrink-0" />
          )}

          <span className="relative flex h-4 w-4 shrink-0">
            <input
              type="checkbox"
              checked={removed}
              disabled={inherited || building}
              onChange={() =>
                setSelected((s) => toggleSelection(s, node.path))
              }
              className="peer absolute inset-0 m-0 h-4 w-4 cursor-pointer opacity-0 disabled:cursor-not-allowed"
              aria-label={`Remove ${node.name}`}
            />
            <span
              className="pointer-events-none flex h-4 w-4 items-center justify-center rounded-[4px] border border-[#34495E] bg-[#0B1220] text-transparent transition-colors peer-checked:border-[#FF4D5A] peer-checked:bg-[#FF4D5A] peer-checked:text-[#FFFFFF] peer-hover:border-[#64748B] peer-focus-visible:ring-2 peer-focus-visible:ring-[#66E5FF] peer-disabled:opacity-50"
            >
              <Check size={11} strokeWidth={3.5} />
            </span>
          </span>

          {node.isDir ? (
            <button
              onClick={() => toggleExpand(node.path)}
              className={`flex min-w-0 flex-1 items-center gap-2.5 rounded ${focusRing}`}
              tabIndex={-1}
            >
              {label}
            </button>
          ) : (
            <div className="flex min-w-0 flex-1 items-center gap-2.5">
              {label}
            </div>
          )}

          <span className="w-20 shrink-0 text-right text-xs tabular-nums text-[#64748B]">
            {formatBytes(node.size)}
          </span>
        </div>

        {node.isDir && open && (
          <ul>
            {node.children.map((child) => renderNode(child, depth + 1))}
          </ul>
        )}
      </li>
    );
  }

  return (
    <div
      className={`${sans.className} min-h-screen bg-[#080B10] text-[#F4F8FC] antialiased`}
    >
      <div className="mx-auto max-w-[1200px] px-5 pb-16 sm:px-8">
        {/* HEADER */}
        <header className="flex h-16 items-center justify-between border-b border-[#263548]">
          <div className="flex items-baseline gap-3">
            <span className="text-[17px] font-semibold tracking-tight">
              Janus
            </span>
            <span className="h-3.5 w-px self-center bg-[#34495E]" />
            <span className="text-sm text-[#64748B]">ZIP organizer</span>
          </div>

          <p className="hidden text-sm text-[#A8B4C2] sm:block">
            Runs in your browser. Nothing is uploaded.
          </p>
        </header>

        <input
          ref={inputRef}
          type="file"
          accept=".zip,application/zip"
          hidden
          onChange={(e) => onPick(e.target.files?.[0])}
        />

        {/* ERROR */}
        {error && (
          <div
            role="alert"
            className="mt-6 flex items-start gap-3 rounded-lg border border-[#FF4D5A]/30 bg-[#FF4D5A]/[0.08] px-4 py-3 text-sm text-[#F4F8FC]"
          >
            <CircleAlert size={17} className="mt-0.5 shrink-0 text-[#FF4D5A]" />
            <span className="text-[#A8B4C2]">{error}</span>
          </div>
        )}

        {/* EMPTY STATE */}
        {!file && (
          <main className="pt-16 sm:pt-24">
            <div className="max-w-2xl">
              <h1 className="text-4xl font-semibold leading-[1.1] tracking-[-0.03em] sm:text-5xl">
                Take out what you don&rsquo;t need from a ZIP.
              </h1>
              <p className="mt-5 max-w-lg text-base leading-relaxed text-[#A8B4C2]">
                Open an archive, tick the files and folders to drop, then
                download a cleaned copy. The original stays untouched.
              </p>
            </div>

            <section
              onDragOver={(e) => {
                e.preventDefault();
                setDragging(true);
              }}
              onDragLeave={() => setDragging(false)}
              onDrop={(e) => {
                e.preventDefault();
                setDragging(false);
                onPick(e.dataTransfer.files?.[0]);
              }}
              className={`mt-12 flex flex-col items-center rounded-xl border border-dashed px-6 py-16 text-center transition-colors sm:py-20 ${
                dragging
                  ? "border-[#00D9FF] bg-[#00D9FF]/[0.06]"
                  : "border-[#34495E] bg-[#111821]"
              }`}
            >
              <div className="flex h-12 w-12 items-center justify-center rounded-lg border border-[#263548] bg-[#0B1220] text-[#00D9FF]">
                <Upload size={21} strokeWidth={1.5} />
              </div>

              <p className="mt-5 text-base font-medium">
                {dragging ? "Release to open" : "Drop a .zip file here"}
              </p>
              <p className="mt-1.5 text-sm text-[#64748B]">
                Encrypted archives aren&rsquo;t supported.
              </p>

              <button
                onClick={() => inputRef.current?.click()}
                className={`mt-7 rounded-lg bg-[#00D9FF] px-5 py-2.5 text-sm font-semibold text-[#080B10] transition-colors hover:bg-[#66E5FF] ${focusRing}`}
              >
                Choose a file
              </button>
            </section>
          </main>
        )}

        {/* WORKSPACE */}
        {file && (
          <main className="grid gap-6 pt-8 lg:grid-cols-[minmax(0,1fr)_320px]">
            {/* EXPLORER */}
            <section className="min-w-0 overflow-hidden rounded-xl border border-[#263548] bg-[#111821]">
              <div className="flex items-center justify-between gap-4 border-b border-[#263548] px-4 py-3">
                <div className="flex min-w-0 items-center gap-3">
                  <FileArchive
                    size={18}
                    strokeWidth={1.5}
                    className="shrink-0 text-[#00D9FF]"
                  />
                  <div className="min-w-0">
                    <p className="truncate text-sm font-medium">{file.name}</p>
                    <p className="text-xs tabular-nums text-[#64748B]">
                      {formatBytes(file.size)} on disk
                    </p>
                  </div>
                </div>

                <div className="flex shrink-0 items-center gap-1.5">
                  <button
                    onClick={() => expandAll(tree.children)}
                    className={`rounded-md px-2.5 py-1.5 text-xs text-[#A8B4C2] transition-colors hover:bg-[#162333] hover:text-[#F4F8FC] ${focusRing}`}
                  >
                    Expand all
                  </button>
                  <button
                    onClick={collapseAll}
                    className={`rounded-md px-2.5 py-1.5 text-xs text-[#A8B4C2] transition-colors hover:bg-[#162333] hover:text-[#F4F8FC] ${focusRing}`}
                  >
                    Collapse all
                  </button>
                </div>
              </div>

              <div className="flex items-center justify-between border-b border-[#263548] bg-[#0B1220] py-2 pl-[64px] pr-4 text-xs text-[#64748B]">
                <span>Name</span>
                <span className="w-20 text-right">Size</span>
              </div>

              <div className="max-h-[560px] overflow-auto py-1.5">
                {tree.children.length > 0 ? (
                  <ul>{tree.children.map((node) => renderNode(node, 0))}</ul>
                ) : (
                  <div className="py-16 text-center text-sm text-[#64748B]">
                    This archive has no files in it.
                  </div>
                )}
              </div>

              <div className="border-t border-[#263548] bg-[#0B1220] px-4 py-2.5 text-xs text-[#64748B]">
                Ticked items are removed from the new archive.
              </div>
            </section>

            {/* SIDE PANEL */}
            <aside className="lg:sticky lg:top-6 lg:self-start">
              <div className="rounded-xl border border-[#263548] bg-[#111821] p-5">
                <div className="flex items-baseline justify-between">
                  <h2 className="text-sm font-medium text-[#A8B4C2]">
                    After cleanup
                  </h2>
                  <button
                    onClick={() => {
                      setSelected(new Set());
                      setStatus("idle");
                      setProgress(0);
                    }}
                    disabled={selected.size === 0 || building}
                    className={`flex items-center gap-1.5 rounded text-xs text-[#A8B4C2] transition-colors hover:text-[#F4F8FC] disabled:pointer-events-none disabled:opacity-30 ${focusRing}`}
                  >
                    <RotateCcw size={12} />
                    Undo all
                  </button>
                </div>

                <p className="mt-3 text-3xl font-semibold tabular-nums tracking-tight">
                  {formatBytes(Math.max(0, totalBytes - summary.bytes))}
                </p>
                <p className="mt-1 text-sm tabular-nums text-[#64748B]">
                  of {formatBytes(totalBytes)} uncompressed
                </p>

                <div
                  className="mt-5 flex h-1.5 overflow-hidden rounded-full bg-[#162333]"
                  role="img"
                  aria-label={`${removedPct.toFixed(0)} percent of the archive is marked for removal`}
                >
                  <div
                    className="h-full bg-[#00D9FF] transition-[width] duration-300"
                    style={{ width: `${100 - removedPct}%` }}
                  />
                  <div
                    className="h-full bg-[#FF4D5A] transition-[width] duration-300"
                    style={{ width: `${removedPct}%` }}
                  />
                </div>

                <dl className="mt-6 divide-y divide-[#263548] border-t border-[#263548] text-sm">
                  {[
                    { label: "Files", value: fileCount, tone: "" },
                    { label: "Folders", value: folderCount, tone: "" },
                    {
                      label: "Removing",
                      value: summary.files,
                      tone: summary.files > 0 ? "text-[#FF4D5A]" : "",
                    },
                    { label: "Keeping", value: keptCount, tone: "text-[#35E69B]" },
                  ].map((row) => (
                    <div
                      key={row.label}
                      className="flex items-center justify-between py-2.5"
                    >
                      <dt className="text-[#A8B4C2]">{row.label}</dt>
                      <dd className={`font-medium tabular-nums ${row.tone}`}>
                        {row.value}
                      </dd>
                    </div>
                  ))}
                </dl>

                <div className="mt-2 text-xs tabular-nums text-[#64748B]">
                  {summary.files > 0
                    ? `${formatBytes(summary.bytes)} will be removed`
                    : "Nothing marked yet"}
                </div>

                <button
                  onClick={rebuild}
                  disabled={building || keptCount === 0}
                  className={`mt-6 flex w-full items-center justify-center gap-2 rounded-lg bg-[#00D9FF] px-4 py-3 text-sm font-semibold text-[#080B10] transition-colors hover:bg-[#66E5FF] disabled:cursor-not-allowed disabled:bg-[#263548] disabled:text-[#64748B] ${focusRing}`}
                >
                  <Download size={16} strokeWidth={2} />
                  {building ? `Building… ${progress}%` : "Download cleaned ZIP"}
                </button>

                {building && (
                  <div
                    className="mt-3 h-1 overflow-hidden rounded-full bg-[#162333]"
                    role="progressbar"
                    aria-valuemin={0}
                    aria-valuemax={100}
                    aria-valuenow={progress}
                  >
                    <div
                      className="h-full bg-[#00D9FF] transition-[width] duration-150"
                      style={{ width: `${progress}%` }}
                    />
                  </div>
                )}

                {status === "done" && (
                  <p className="mt-3 flex items-start gap-2 text-xs text-[#A8B4C2]">
                    <Check size={14} className="mt-px shrink-0 text-[#35E69B]" />
                    <span className="min-w-0 break-words">
                      Downloaded {cleanedName}
                    </span>
                  </p>
                )}

                {keptCount === 0 && fileCount > 0 && (
                  <p className="mt-3 text-xs text-[#A8B4C2]">
                    Every file is marked for removal. Keep at least one to
                    download.
                  </p>
                )}
              </div>

              <button
                onClick={closeArchive}
                disabled={building}
                className={`mt-3 flex w-full items-center justify-center gap-2 rounded-lg border border-[#263548] px-4 py-2.5 text-sm text-[#A8B4C2] transition-colors hover:border-[#34495E] hover:text-[#F4F8FC] disabled:pointer-events-none disabled:opacity-40 ${focusRing}`}
              >
                <X size={14} />
                Close archive
              </button>
            </aside>
          </main>
        )}
      </div>
    </div>
  );
}
